-- STATUS: already run (2026-08-22) — marketing_tasks reloaded to the full 265 rows
-- ============================================================================
--  repair_tasks.sql — reload marketing_intakes + marketing_tasks.
--
--  Run when a verification count shows marketing_tasks short of 265 rows.
--  Safe to re-run. Touches no other table.
--
--  The rows are inserted in batches of 25 rather than one 265-row statement.
--  bootstrap.sql loaded every other table correctly and only this one came up
--  short, which points at the size of that single 32KB INSERT rather than at
--  the data — batching removes that variable entirely, and any batch that
--  fails now reports its own error instead of vanishing into a partial result.
--
--  Parents are reloaded first: fk_tasks_intake is ON DELETE CASCADE, so
--  loading tasks against a missing intake would silently drop them.
--  marketing_intakes uses ids 2-16, not 1-15 — that is correct, not a gap
--  to fix.
-- ============================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM marketing_tasks;
DELETE FROM marketing_intakes;

-- ── marketing_intakes (15 rows, 1 batch(es)) ────────────────────

-- ── marketing_tasks (265 rows, 11 batches) ────────────────────────

SET FOREIGN_KEY_CHECKS = 1;

-- Expect: intakes 15, tasks 265, orphans 0.
SELECT COUNT(*) AS intakes FROM marketing_intakes;
SELECT COUNT(*) AS tasks   FROM marketing_tasks;
SELECT COUNT(*) AS orphans FROM marketing_tasks t
  LEFT JOIN marketing_intakes i ON i.id = t.intake_id WHERE i.id IS NULL;
